<?php class UserController extends CrudController{function __construct(){$this->table='users';$this->title='User';$this->fields=['nama'=>'Nama','username'=>'Username','role'=>'Role','status'=>'Status'];$this->view='users';}function store(){require_admin();$password=$_POST['password']??'';if(strlen($password)<6)exit('Password minimal 6 karakter.');$db=Database::connect();$s=$db->prepare('INSERT INTO users(nama,username,password,role,status) VALUES(?,?,?,?,?)');$s->execute([$_POST['nama']??'',$_POST['username']??'',password_hash($password,PASSWORD_DEFAULT),$_POST['role']??'kasir',$_POST['status']??'aktif']);flash('success','User berhasil ditambahkan.');redirect('?page=users');}function reset(){require_admin();$db=Database::connect();$s=$db->prepare('SELECT * FROM users WHERE id=?');$s->execute([$_GET['id']]);$target=$s->fetch();$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){$admin=$db->prepare('SELECT password FROM users WHERE id=?');$admin->execute([auth()['id']]);if(!password_verify($_POST['admin_password']??'',$admin->fetchColumn()))$error='Password admin salah.';elseif(strlen($_POST['new_password']??'')<6)$error='Password baru minimal 6 karakter.';else{$u=$db->prepare('UPDATE users SET password=? WHERE id=?');$u->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$target['id']]);flash('success','Password user berhasil direset.');redirect('?page=users');}}$pageTitle='Reset Password';require __DIR__.'/../views/users/reset.php';}}
